INSERT INTO repo_subtopics (subtopic_id, name, subtopic_no, description, subtopic_sd_id, review_status, status, version) VALUES ('SUB_COURSE_048_M4_S6', 'multiplexing', '6', 'multiplexing: Sharing one measurement or communication path among multiple signals using controlled switching or addressing. In Signal Conditioning and Data Acquisition, the focus is on the analysis, design, implementation, interpretation, or evaluation of multiplexing within Electrical Measurements and Instrumentation, particularly where the Signal Conditioning and Data Acquisition module establishes its technical context.', 'SSD_COURSE_048_M4_S6', 'Semantically_Audited', 'Active', '4.0'), ('SUB_COURSE_048_M5_S1', 'traceability', '1', 'traceability: Property of a measurement result that can be related to a reference through a documented unbroken chain of calibrations, each contributing to uncertainty. In Measurement Systems and Calibration, the focus is on the analysis, design, implementation, interpretation, or evaluation of traceability within Electrical Measurements and Instrumentation, particularly where the Measurement Systems and Calibration module establishes its technical context.', 'SSD_COURSE_048_M5_S1', 'Semantically_Audited', 'Active', '4.0'), ('SUB_COURSE_048_M5_S2', 'calibration procedures', '2', 'calibration procedures: Documented procedures for establishing the relationship between measurement indications and reference values under specified conditions, including the associated measurement uncertainty. In Measurement Systems and Calibration, the focus is on the analysis, design, implementation, interpretation, or evaluation of calibration procedures within Electrical Measurements and Instrumentation, particularly where the Measurement Systems and Calibration module establishes its technical context.', 'SSD_COURSE_048_M5_S2', 'Semantically_Audited', 'Active', '4.0'), ('SUB_COURSE_048_M5_S3', 'reference standards', '3', 'reference standards: Measurement standards used as references for calibration, verification, comparison, or dissemination of measurement values. In Measurement Systems and Calibration, the focus is on the analysis, design, implementation, interpretation, or evaluation of reference standards within Electrical Measurements and Instrumentation, particularly where the Measurement Systems and Calibration module establishes its technical context.', 'SSD_COURSE_048_M5_S3', 'Semantically_Audited', 'Active', '4.0'), ('SUB_COURSE_048_M5_S4', 'adjustment versus calibration', '4', 'adjustment versus calibration refers to the distinction between calibration, which establishes the measurement relationship, and adjustment, which changes an instrument so its indication meets specified requirements. In Measurement Systems and Calibration, the focus is on the analysis, design, implementation, interpretation, or evaluation of adjustment versus calibration within Electrical Measurements and Instrumentation, particularly where the Measurement Systems and Calibration module establishes its technical context.', 'SSD_COURSE_048_M5_S4', 'Semantically_Audited', 'Active', '4.0'), ('SUB_COURSE_048_M6_S1', 'uncertainty components', '1', 'uncertainty components: Individual contributions to measurement uncertainty, such as repeatability, resolution, calibration, environmental effects, and other relevant sources. In Uncertainty and Statistical Evaluation, the focus is on the analysis, design, implementation, interpretation, or evaluation of uncertainty components within Electrical Measurements and Instrumentation, particularly where the Uncertainty and Statistical Evaluation module establishes its technical context.', 'SSD_COURSE_048_M6_S1', 'Semantically_Audited', 'Active', '4.0'), ('SUB_COURSE_048_M6_S2', 'propagation', '2', 'propagation: Calculation of how input uncertainties contribute to uncertainty in a derived measurement result. In Uncertainty and Statistical Evaluation, the focus is on the analysis, design, implementation, interpretation, or evaluation of propagation within Electrical Measurements and Instrumentation, particularly where the Uncertainty and Statistical Evaluation module establishes its technical context.', 'SSD_COURSE_048_M6_S2', 'Semantically_Audited', 'Active', '4.0'), ('SUB_COURSE_048_M6_S3', 'repeatability', '3', 'repeatability: Closeness of agreement among results obtained under the same measurement procedure, operator, system, location, and short time interval. In Uncertainty and Statistical Evaluation, the focus is on the analysis, design, implementation, interpretation, or evaluation of repeatability within Electrical Measurements and Instrumentation, particularly where the Uncertainty and Statistical Evaluation module establishes its technical context.', 'SSD_COURSE_048_M6_S3', 'Semantically_Audited', 'Active', '4.0'), ('SUB_COURSE_048_M6_S4', 'Measurement reproducibility', '4', 'Measurement reproducibility: Closeness of agreement among measurement results obtained under specified reproducibility conditions, including changes in measurement operators, systems, locations, or time as defined by the measurement procedure. In Uncertainty and Statistical Evaluation, the focus is on curricular scope: Electrical Measurements and Instrumentation; The concept is represented at the level of the stated mechanism, properties, constraints, and application criteria.', 'SSD_COURSE_048_M6_S4', 'Semantically_Audited', 'Active', '4.0'), ('SUB_COURSE_048_M6_S5', 'confidence intervals', '5', 'confidence intervals: Statistical intervals constructed from sample data to estimate a population parameter with a stated confidence level under defined assumptions. In Uncertainty and Statistical Evaluation, the focus is on the analysis, design, implementation, interpretation, or evaluation of confidence intervals within Electrical Measurements and Instrumentation, particularly where the Uncertainty and Statistical Evaluation module establishes its technical context.', 'SSD_COURSE_048_M6_S5', 'Semantically_Audited', 'Active', '4.0'), ('SUB_COURSE_048_M7_S1', 'power measurements', '1', 'power measurements refers to the methods and principles used to obtain and interpret measurements of power measurements under specified conditions. In Instrumentation Applications, the focus is on the analysis, design, implementation, interpretation, or evaluation of power measurements within Electrical Measurements and Instrumentation, particularly where the Instrumentation Applications module establishes its technical context.', 'SSD_COURSE_048_M7_S1', 'Semantically_Audited', 'Active', '4.0'), ('SUB_COURSE_048_M7_S2', 'energy measurement', '2', 'energy measurement refers to the methods and principles used to obtain and interpret measurements of energy measurement under specified conditions. In Instrumentation Applications, the focus is on the analysis, design, implementation, interpretation, or evaluation of energy measurement within Electrical Measurements and Instrumentation, particularly where the Instrumentation Applications module establishes its technical context.', 'SSD_COURSE_048_M7_S2', 'Semantically_Audited', 'Active', '4.0'), ('SUB_COURSE_048_M7_S3', 'process instrumentation', '3', 'process instrumentation: Sensors, transmitters, analysers, signal-conditioning devices, and related measurement systems used to observe process variables such as temperature, pressure, flow, and level. In Instrumentation Applications, the focus is on the analysis, design, implementation, interpretation, or evaluation of process instrumentation within Electrical Measurements and Instrumentation, particularly where the Instrumentation Applications module establishes its technical context.', 'SSD_COURSE_048_M7_S3', 'Semantically_Audited', 'Active', '4.0'), ('SUB_COURSE_048_M7_S4', 'data logging', '4', 'data logging: Automatic recording and storage of measurement data with associated time, channels, and acquisition settings. In Instrumentation Applications, the focus is on the analysis, design, implementation, interpretation, or evaluation of data logging within Electrical Measurements and Instrumentation, particularly where the Instrumentation Applications module establishes its technical context.', 'SSD_COURSE_048_M7_S4', 'Semantically_Audited', 'Active', '4.0'), ('SUB_COURSE_048_M7_S5', 'remote measurement', '5', 'remote measurement refers to the methods and principles used to obtain and interpret measurements of remote measurement under specified conditions. In Instrumentation Applications, the focus is on the analysis, design, implementation, interpretation, or evaluation of remote measurement within Electrical Measurements and Instrumentation, particularly where the Instrumentation Applications module establishes its technical context.', 'SSD_COURSE_048_M7_S5', 'Semantically_Audited', 'Active', '4.0'), ('SUB_COURSE_049_M1_S1', 'continuous/discrete signals', '1', 'continuous/discrete signals: Representations of physical or mathematical quantities that vary with time, space, or another independent variable and carry information about continuous/discrete signals. In Signal Representation, the focus is on the analysis, design, implementation, interpretation, or evaluation of continuous/discrete signals within Signals and Systems, particularly where the Signal Representation module establishes its technical context.', 'SSD_COURSE_049_M1_S1', 'Semantically_Audited', 'Active', '4.0'), ('SUB_COURSE_049_M1_S2', 'energy and power', '2', 'energy and power refers to a signal measure based on the integral or average of squared magnitude, used to distinguish energy-type and power-type signals. In Signal Representation, the focus is on the analysis, design, implementation, interpretation, or evaluation of energy and power within Signals and Systems, particularly where the Signal Representation module establishes its technical context.', 'SSD_COURSE_049_M1_S2', 'Semantically_Audited', 'Active', '4.0'), ('SUB_COURSE_049_M1_S3', 'transformations', '3', 'transformations: Operations that change a signal''s amplitude, time scale, shift, reversal, or other representation. In Signal Representation, the focus is on the analysis, design, implementation, interpretation, or evaluation of transformations within Signals and Systems, particularly where the Signal Representation module establishes its technical context.', 'SSD_COURSE_049_M1_S3', 'Semantically_Audited', 'Active', '4.0'), ('SUB_COURSE_049_M1_S4', 'complex exponentials', '4', 'complex exponentials: Exponentials with complex arguments that form fundamental building blocks for continuous- and discrete-time signal analysis. In Signal Representation, the focus is on the analysis, design, implementation, interpretation, or evaluation of complex exponentials within Signals and Systems, particularly where the Signal Representation module establishes its technical context.', 'SSD_COURSE_049_M1_S4', 'Semantically_Audited', 'Active', '4.0'), ('SUB_COURSE_049_M2_S1', 'linearity', '1', 'linearity refers to a system property in which scaling and addition of inputs produce correspondingly scaled and added outputs. In Linear Time-Invariant Systems, the focus is on the analysis, design, implementation, interpretation, or evaluation of linearity within Signals and Systems, particularly where the Linear Time-Invariant Systems module establishes its technical context.', 'SSD_COURSE_049_M2_S1', 'Semantically_Audited', 'Active', '4.0'), ('SUB_COURSE_049_M2_S2', 'time invariance', '2', 'time invariance refers to a system property in which shifting the input in time produces the same shift in the output. In Linear Time-Invariant Systems, the focus is on the analysis, design, implementation, interpretation, or evaluation of time invariance within Signals and Systems, particularly where the Linear Time-Invariant Systems module establishes its technical context.', 'SSD_COURSE_049_M2_S2', 'Semantically_Audited', 'Active', '4.0'), ('SUB_COURSE_049_M2_S3', 'convolution', '3', 'convolution refers to an operation that combines an input signal with a system impulse response to obtain the output of an LTI system. In Linear Time-Invariant Systems, the focus is on the analysis, design, implementation, interpretation, or evaluation of convolution within Signals and Systems, particularly where the Linear Time-Invariant Systems module establishes its technical context.', 'SSD_COURSE_049_M2_S3', 'Semantically_Audited', 'Active', '4.0'), ('SUB_COURSE_049_M2_S4', 'impulse response', '4', 'impulse response refers to the output of a system produced by an ideal impulse input and a complete characterisation of an LTI system. In Linear Time-Invariant Systems, the focus is on the analysis, design, implementation, interpretation, or evaluation of impulse response within Signals and Systems, particularly where the Linear Time-Invariant Systems module establishes its technical context.', 'SSD_COURSE_049_M2_S4', 'Semantically_Audited', 'Active', '4.0'), ('SUB_COURSE_049_M2_S5', 'system properties', '5', 'system properties: Characteristics such as linearity, time invariance, causality, stability, and memory used to classify systems. In Linear Time-Invariant Systems, the focus is on the analysis, design, implementation, interpretation, or evaluation of system properties within Signals and Systems, particularly where the Linear Time-Invariant Systems module establishes its technical context.', 'SSD_COURSE_049_M2_S5', 'Semantically_Audited', 'Active', '4.0'), ('SUB_COURSE_049_M3_S1', 'Fourier series', '1', 'Fourier series: Representation of a periodic signal as a sum of harmonically related sinusoidal or complex-exponential components. In Fourier Analysis, the focus is on the analysis, design, implementation, interpretation, or evaluation of Fourier series within Signals and Systems, particularly where the Fourier Analysis module establishes its technical context.', 'SSD_COURSE_049_M3_S1', 'Semantically_Audited', 'Active', '4.0'), ('SUB_COURSE_049_M3_S2', 'Fourier transform', '2', 'Fourier transform refers to a transform that represents an aperiodic signal in terms of its frequency components. In Fourier Analysis, the focus is on the analysis, design, implementation, interpretation, or evaluation of Fourier transform within Signals and Systems, particularly where the Fourier Analysis module establishes its technical context.', 'SSD_COURSE_049_M3_S2', 'Semantically_Audited', 'Active', '4.0'), ('SUB_COURSE_049_M3_S3', 'spectra', '3', 'spectra: Frequency-domain representations showing how signal amplitude, phase, or power is distributed with frequency. In Fourier Analysis, the focus is on the analysis, design, implementation, interpretation, or evaluation of spectra within Signals and Systems, particularly where the Fourier Analysis module establishes its technical context.', 'SSD_COURSE_049_M3_S3', 'Semantically_Audited', 'Active', '4.0'), ('SUB_COURSE_049_M3_S4', 'bandwidth', '4', 'bandwidth refers to the range of frequencies over which a signal or system has significant or specified response. In Fourier Analysis, the focus is on the analysis, design, implementation, interpretation, or evaluation of bandwidth within Signals and Systems, particularly where the Fourier Analysis module establishes its technical context.', 'SSD_COURSE_049_M3_S4', 'Semantically_Audited', 'Active', '4.0'), ('SUB_COURSE_049_M3_S5', 'filtering', '5', 'filtering: Selective attenuation or passage of signal components according to frequency, time, spatial characteristics, or other defined criteria. In Fourier Analysis, the focus is on concept-level scope: the defining mechanism, properties, constraints, and application criteria; curricular context is recorded in Concept_Category and Typical_Modules.', 'SSD_COURSE_049_M3_S5', 'Semantically_Audited', 'Active', '4.0'), ('SUB_COURSE_049_M4_S1', 'Laplace transform', '1', 'Laplace transform refers to a transform for discrete-time signals and systems that generalises frequency-domain analysis using a complex variable. In Laplace Transform and System Analysis, the focus is on the analysis, design, implementation, interpretation, or evaluation of Z transform within Signals and Systems, particularly where the Z Transform and Discrete-Time Systems module establishes its technical context.', 'SSD_COURSE_049_M4_S1', 'Semantically_Audited', 'Active', '4.0'), ('SUB_COURSE_049_M4_S2', 'transfer functions', '2', 'transfer functions: Mathematical representations relating the output to the input of a linear time-invariant system in a transform domain under stated initial-condition assumptions. In Laplace Transform and System Analysis, the focus is on concept-level scope: the defining mechanism, properties, constraints, and application criteria; curricular context is recorded in Concept_Category and Typical_Modules.', 'SSD_COURSE_049_M4_S2', 'Semantically_Audited', 'Active', '4.0'), ('SUB_COURSE_049_M4_S3', 'poles and zeros', '3', 'poles and zeros: Values of the complex-frequency variable that make a system function infinite or zero, respectively. In Laplace Transform and System Analysis, the focus is on the analysis, design, implementation, interpretation, or evaluation of poles and zeros within Signals and Systems, particularly where the Laplace Transform and System Analysis module establishes its technical context.', 'SSD_COURSE_049_M4_S3', 'Semantically_Audited', 'Active', '4.0'), ('SUB_COURSE_049_M4_S4', 'stability', '4', 'stability: Property describing whether a system returns toward an acceptable state or bounded response after a perturbation, according to the stability criterion appropriate to the system model. In Laplace Transform and System Analysis, the focus is on concept-level scope: the defining mechanism, properties, constraints, and application criteria; curricular context is recorded in Concept_Category and Typical_Modules.', 'SSD_COURSE_049_M4_S4', 'Semantically_Audited', 'Active', '4.0'), ('SUB_COURSE_049_M5_S1', 'Z transform', '1', 'Z transform refers to a transform for discrete-time signals and systems that generalises frequency-domain analysis using a complex variable. In Z Transform and Discrete-Time Systems, the focus is on the analysis, design, implementation, interpretation, or evaluation of Z transform within Signals and Systems, particularly where the Z Transform and Discrete-Time Systems module establishes its technical context.', 'SSD_COURSE_049_M5_S1', 'Semantically_Audited', 'Active', '4.0'), ('SUB_COURSE_049_M5_S2', 'Region of Convergence (ROC)', '2', 'ROC: Region of Convergence, the set of complex values for which a Z-transform or related transform converges. In Z Transform and Discrete-Time Systems, the focus is on the analysis, design, implementation, interpretation, or evaluation of ROC within Signals and Systems, particularly where the Z Transform and Discrete-Time Systems module establishes its technical context.', 'SSD_COURSE_049_M5_S2', 'Semantically_Audited', 'Active', '4.0'), ('SUB_COURSE_049_M5_S3', 'difference equations', '3', 'difference equations: Discrete-time equations relating current and past input or output samples. In Z Transform and Discrete-Time Systems, the focus is on the analysis, design, implementation, interpretation, or evaluation of difference equations within Signals and Systems, particularly where the Z Transform and Discrete-Time Systems module establishes its technical context.', 'SSD_COURSE_049_M5_S3', 'Semantically_Audited', 'Active', '4.0'), ('SUB_COURSE_049_M5_S4', 'digital-system response', '4', 'digital-system response: Output behaviour of a discrete-time system for specified inputs and initial conditions. In Z Transform and Discrete-Time Systems, the focus is on the analysis, design, implementation, interpretation, or evaluation of digital-system response within Signals and Systems, particularly where the Z Transform and Discrete-Time Systems module establishes its technical context.', 'SSD_COURSE_049_M5_S4', 'Semantically_Audited', 'Active', '4.0'), ('SUB_COURSE_049_M6_S1', 'Nyquist rate', '1', 'Nyquist rate: Minimum theoretical sampling rate equal to twice the highest frequency present in a band-limited signal. In Sampling and Reconstruction, the focus is on the analysis, design, implementation, interpretation, or evaluation of Nyquist rate within Signals and Systems, particularly where the Sampling and Reconstruction module establishes its technical context.', 'SSD_COURSE_049_M6_S1', 'Semantically_Audited', 'Active', '4.0'), ('SUB_COURSE_049_M6_S2', 'aliasing', '2', 'aliasing: Distortion caused when sampling makes different continuous-time frequency components indistinguishable. In Sampling and Reconstruction, the focus is on the analysis, design, implementation, interpretation, or evaluation of aliasing within Signals and Systems, particularly where the Sampling and Reconstruction module establishes its technical context.', 'SSD_COURSE_049_M6_S2', 'Semantically_Audited', 'Active', '4.0'), ('SUB_COURSE_049_M6_S3', 'reconstruction', '3', 'reconstruction: Recovery of a continuous-time signal from discrete samples under appropriate sampling and filtering conditions. In Sampling and Reconstruction, the focus is on the analysis, design, implementation, interpretation, or evaluation of reconstruction within Signals and Systems, particularly where the Sampling and Reconstruction module establishes its technical context.', 'SSD_COURSE_049_M6_S3', 'Semantically_Audited', 'Active', '4.0'), ('SUB_COURSE_049_M6_S4', 'quantization', '4', 'quantization: Mapping continuous-amplitude or high-resolution sample values to a finite set of discrete levels. In Sampling and Reconstruction, the focus is on the analysis, design, implementation, interpretation, or evaluation of quantization within Signals and Systems, particularly where the Sampling and Reconstruction module establishes its technical context.', 'SSD_COURSE_049_M6_S4', 'Semantically_Audited', 'Active', '4.0'), ('SUB_COURSE_049_M7_S1', 'frequency response', '1', 'frequency response: System gain and phase as functions of frequency for sinusoidal steady-state inputs. In Applications and System Characterization, the focus is on the analysis, design, implementation, interpretation, or evaluation of frequency response within Signals and Systems, particularly where the Applications and System Characterization module establishes its technical context.', 'SSD_COURSE_049_M7_S1', 'Semantically_Audited', 'Active', '4.0'), ('SUB_COURSE_049_M7_S2', 'filters', '2', 'filters: Systems designed to pass selected frequency components while attenuating others. In Applications and System Characterization, the focus is on the analysis, design, implementation, interpretation, or evaluation of filters within Signals and Systems, particularly where the Applications and System Characterization module establishes its technical context.', 'SSD_COURSE_049_M7_S2', 'Semantically_Audited', 'Active', '4.0'), ('SUB_COURSE_049_M7_S3', 'modulation concepts', '3', 'modulation concepts: Changing a carrier signal according to an information signal to enable transmission or processing. In Applications and System Characterization, the focus is on the analysis, design, implementation, interpretation, or evaluation of modulation concepts within Signals and Systems, particularly where the Applications and System Characterization module establishes its technical context.', 'SSD_COURSE_049_M7_S3', 'Semantically_Audited', 'Active', '4.0'), ('SUB_COURSE_049_M7_S4', 'signal measurement', '4', 'signal measurement refers to the methods and principles used to obtain and interpret measurements of signal measurement under specified conditions. In Applications and System Characterization, the focus is on the analysis, design, implementation, interpretation, or evaluation of signal measurement within Signals and Systems, particularly where the Applications and System Characterization module establishes its technical context.', 'SSD_COURSE_049_M7_S4', 'Semantically_Audited', 'Active', '4.0'), ('SUB_COURSE_050_M1_S1', 'environmental rights', '1', 'environmental rights: Legal rights or protections relating to environmental quality, health, access to information, or participation. In Foundations of Environmental Law, the focus is on the analysis, design, implementation, interpretation, or evaluation of environmental rights within Environmental Law and Environmental Governance, particularly where the Foundations of Environmental Law module establishes its technical context.', 'SSD_COURSE_050_M1_S1', 'Semantically_Audited', 'Active', '4.0'), ('SUB_COURSE_050_M1_S2', 'public trust', '2', 'public trust refers to a legal doctrine under which certain natural resources are held or managed for public benefit. In Foundations of Environmental Law, the focus is on the analysis, design, implementation, interpretation, or evaluation of public trust within Environmental Law and Environmental Governance, particularly where the Foundations of Environmental Law module establishes its technical context.', 'SSD_COURSE_050_M1_S2', 'Semantically_Audited', 'Active', '4.0'), ('SUB_COURSE_050_M1_S3', 'precaution', '3', 'precaution refers to a decision-making principle supporting preventive action where serious environmental harm is plausible despite scientific uncertainty. In Foundations of Environmental Law, the focus is on the analysis, design, implementation, interpretation, or evaluation of precaution within Environmental Law and Environmental Governance, particularly where the Foundations of Environmental Law module establishes its technical context.', 'SSD_COURSE_050_M1_S3', 'Semantically_Audited', 'Active', '4.0'), ('SUB_COURSE_050_M1_S4', 'polluter pays', '4', 'polluter pays refers to a principle that places the costs of preventing, controlling, or remedying pollution on the responsible polluter. In Foundations of Environmental Law, the focus is on the analysis, design, implementation, interpretation, or evaluation of polluter pays within Environmental Law and Environmental Governance, particularly where the Foundations of Environmental Law module establishes its technical context.', 'SSD_COURSE_050_M1_S4', 'Semantically_Audited', 'Active', '4.0'), ('SUB_COURSE_050_M1_S5', 'sustainable development', '5', 'sustainable development refers to a governance principle seeking to meet present needs while maintaining environmental and social conditions for future generations. In Foundations of Environmental Law, the focus is on the analysis, design, implementation, interpretation, or evaluation of sustainable development within Environmental Law and Environmental Governance, particularly where the Foundations of Environmental Law module establishes its technical context.', 'SSD_COURSE_050_M1_S5', 'Semantically_Audited', 'Active', '4.0') ON CONFLICT DO NOTHING;